-- LOCAL ONLY. Readiness evidence, not a cross-check closure or human attestation.
-- This deliberately supports only completely structured synthetic paper games.
begin;
create function app.synthetic_event_crosscheck_readiness_candidate_v1(actor uuid,tid uuid,eid uuid)returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare close_row app.event_play_closes%rowtype;preview jsonb;readiness jsonb;manifest jsonb;
begin
 if coalesce(auth.role(),'')<>'service_role' or not exists(select 1 from app.tournament_roles where tournament_id=tid and profile_id=actor and role='director') then return null;end if;
 if not exists(select 1 from app.tournaments where id=tid and status in('open','pending_finalization')) then return jsonb_build_object('status','blocked','code','tournament_unavailable');end if;
 if not exists(select 1 from app.synthetic_paper_fixtures_v1 where tournament_id=tid and event_id=eid and project_ref='nnhcnvksxgxnpvdqjgpg') then return jsonb_build_object('status','blocked','code','synthetic_fixture_required');end if;
 if not exists(select 1 from app.events where tournament_id=tid and id=eid and operational_state='active') then return jsonb_build_object('status','blocked','code','event_unavailable');end if;
 select * into close_row from app.event_play_closes where tournament_id=tid and event_id=eid order by sequence_number desc limit 1;
 if close_row.id is null or close_row.action<>'closed' or not exists(select 1 from app.synthetic_event_provenance_v1 p join app.synthetic_event_artifacts_v1 a on a.id=p.artifact_id and a.tournament_id=p.tournament_id and a.event_id=p.event_id where p.tournament_id=tid and p.event_id=eid and p.entity_table='event_play_closes' and p.entity_id=close_row.id and p.operation_receipt_id=close_row.operation_receipt_id and a.kind='close' and p.source_digest=a.source_digest and a.source_digest=app.synthetic_event_source_v1(actor,tid,eid,'close') and p.record_sha256=encode(extensions.digest(to_jsonb(close_row)::text,'sha256'),'hex') and not p.human_review_claimed and not p.physical_play and not p.money_moved) then return jsonb_build_object('status','blocked','code','synthetic_event_close_required');end if;
 if not exists(select 1 from app.tournament_roles r where r.tournament_id=tid and r.role='cross_checker') then return jsonb_build_object('status','blocked','code','cross_checker_required');end if;
 readiness:=app.event_play_close_readiness_v1(eid);
 if coalesce((readiness->>'scheduledGames')::integer,0)=0 or coalesce((readiness->>'unresolvedGames')::integer,1)<>0 or close_row.scheduled_game_count<>(readiness->>'scheduledGames')::integer or close_row.resolved_game_count<>(readiness->>'resolvedGames')::integer then return jsonb_build_object('status','blocked','code','game_review_incomplete');end if;
 if exists(select 1 from app.canonical_games g where g.tournament_id=tid and g.event_id=eid and not exists(select 1 from app.event_schedule_games sg where sg.tournament_id=tid and sg.event_id=eid and sg.canonical_game_id=g.id)) then return jsonb_build_object('status','blocked','code','unpublished_game_present');end if;
 if exists(select 1 from app.event_schedule_games g where g.tournament_id=tid and g.event_id=eid and not exists(select 1 from app.synthetic_paper_provenance_v1 a join app.synthetic_paper_provenance_v1 b on b.tournament_id=a.tournament_id and b.event_id=a.event_id and b.game_id=a.game_id and b.completion_id=a.completion_id and b.artifact_id=a.artifact_id and b.side_a_sha256=a.side_a_sha256 and b.side_b_sha256=a.side_b_sha256 and b.phase='review' and not b.human_review_claimed and not b.physical_original join app.paper_game_completions c on c.id=a.completion_id and c.canonical_game_id=a.game_id and c.tournament_id=tid and c.event_id=eid join app.canonical_games cg on cg.id=g.canonical_game_id and cg.tournament_id=tid and cg.event_id=eid and cg.state='verified' and cg.winner_side=c.winner_side and cg.margin=c.margin where a.tournament_id=tid and a.event_id=eid and a.game_id=g.canonical_game_id and a.phase='capture' and not a.human_review_claimed and not a.physical_original and app.paper_game_completion_latest_state(c.id)='approved')) then return jsonb_build_object('status','blocked','code','structured_synthetic_review_required');end if;
 if exists(select 1 from app.event_team_games where tournament_id=tid and event_id=eid and state not in('verified','corrected'))
 or exists(select 1 from app.game_corrections c where c.tournament_id=tid and c.event_id=eid and exists(select 1 from app.correction_state_events x where x.correction_id=c.id and x.state='pending') and not exists(select 1 from app.correction_state_events x where x.correction_id=c.id and x.state in('approved','applied','rejected')))
 or exists(select 1 from app.independent_card_correction_lifecycles c where c.tournament_id=tid and c.event_id=eid and exists(select 1 from app.independent_card_correction_state_events x where x.correction_id=c.correction_id and x.state='pending') and not exists(select 1 from app.independent_card_correction_state_events x where x.correction_id=c.correction_id and x.state in('approved','applied','rejected')))
 or exists(select 1 from app.event_disputes d where d.tournament_id=tid and d.event_id=eid and app.event_dispute_is_open(d.id))
 or exists(select 1 from app.device_failure_recoveries d where d.tournament_id=tid and d.event_id=eid and coalesce((select x.state from app.device_failure_recovery_state_events x where x.recovery_id=d.id order by x.transition_sequence desc limit 1),'pending_review') in('pending_review','disputed'))
 or exists(select 1 from app.hybrid_game_cases h where h.tournament_id=tid and h.event_id=eid and coalesce((select x.state from app.hybrid_game_state_events x where x.hybrid_case_id=h.id order by x.transition_sequence desc limit 1),'pending_review')='pending_review')
 or exists(select 1 from app.paper_game_completions p where p.tournament_id=tid and p.event_id=eid and coalesce((select x.state from app.paper_game_completion_state_events x where x.completion_id=p.id order by x.transition_sequence desc limit 1),'pending_review')='pending_review') then return jsonb_build_object('status','blocked','code','open_review_work');end if;
 preview:=public.get_multi_event_award_preview_v1(actor,tid,eid);
 if preview->>'status' is distinct from'preview' then return jsonb_build_object('status','blocked','code','current_preview_required');end if;
 manifest:=jsonb_build_object('version','synthetic-event-crosscheck-readiness-candidate-v1','eventId',eid,'close',to_jsonb(close_row),'gameReadiness',readiness,'previewSourceDigest',preview->'sourceDigest',
 'paperProvenance',(select coalesce(jsonb_agg(to_jsonb(p) order by p.game_id,p.phase,p.operation_receipt_id),'[]') from app.synthetic_paper_provenance_v1 p where p.tournament_id=tid and p.event_id=eid));
 return jsonb_build_object('status','candidate_ready','eventId',eid,'sourceDigest',encode(extensions.digest(convert_to(manifest::text,'utf8'),'sha256'),'hex'),'humanReviewClaimed',false,'physicalPlayClaimed',false,'crosscheckClosed',false,'moneyMoved',false);
end$$;
revoke all on function app.synthetic_event_crosscheck_readiness_candidate_v1(uuid,uuid,uuid)from public,anon,authenticated,service_role;
commit;
